#include <cstdio>
#include <algorithm>
#include <cctype>

const int bufSize = 1000000;

inline int nc()
{
#ifdef DEBUG
    return getchar();
#else
    static char buf[bufSize];
    static char *p1 = buf, *p2 = buf;
    if (p1 == p2) {
        p2 = (p1 = buf) + fread(buf, 1, bufSize, stdin);
        if (p1 == p2) return EOF;
    }
    return static_cast<unsigned char>(*p1++);
#endif
}

template <typename T>
inline T read(T &r)
{
    int c, flag = 1;
    r = 0;
    do {
        c = nc();
        if (c == '-') flag = -1;
    } while (c != EOF && !std::isdigit(c));

    while (c != EOF && std::isdigit(c)) {
        r = r * 10 + c - '0';
        c = nc();
    }
    return r *= flag;
}

const int maxn = 1000100;
int k, q;
long long f[7], ww[7][10];
long long dp[maxn];
int bit[maxn];
int pw[7] = {1, 1, 10, 100, 1000, 10000, 100000};

inline void work(int weight, long long value)
{
    for (int i = 999999; i >= weight; --i)
        dp[i] = std::max(dp[i], dp[i - weight] + value);
}

int main()
{
    read(k);

    for (int i = 1; i <= 6; ++i) {
        read(f[i]);
        ww[i][3] = f[i];
        ww[i][6] = 2 * f[i];
        ww[i][9] = 3 * f[i];
    }

    for (int i = 1; i <= 999999; ++i) {
        bit[i] = bit[i / 10] + 1;
        dp[i] = dp[i % pw[bit[i]]] + ww[bit[i]][i / pw[bit[i]]];
    }

    for (int i = 1; i <= 6; ++i) {
        int num = std::min(3 * (k - 1), 333333 / pw[i]);
        for (int j = 1; j <= num; num -= j, j <<= 1)
            work(3 * pw[i] * j, f[i] * j);
        if (num)
            work(3 * pw[i] * num, f[i] * num);
    }

    read(q);
    for (int i = 1, x; i <= q; ++i) {
        read(x);
        std::printf("%lld\n", dp[x]);
    }

    return 0;
}

